Lemma aslot_client : forall c k, 1 <= c < K_NUM_CLASSES -> 0 <= k < ndist st c ->
  match busy_of X c k with None => junk_at m (aslot_addr L c k) (size_of_class c) | Some b => aslot_busy L m b end ->
  match busy_of X c k with None => junk_at m' (aslot_addr L c k) (size_of_class c) | Some b => aslot_busy L m' b end.
Proof.
